          ],
          "kind": "clock"
        }
      ],
      "parts": [
        {
          "id": "boot",
          "ref": {
            "rom": {
              "k": 7,
              "w": 32,
              "addr": "rv32",
              "lang": "asm",
              "src": "# boot ROM: copy 96 words from flash (0x1000_0000) to RAM 0x400 by DMA, wait, jump\n        li   t0, 0x40000000     # the DMA's registers\n        li   t1, 0x10000000\n        sw   t1, 0(t0)          # source: the flash\n        li   t1, 1024\n        sw   t1, 4(t0)          # destination: RAM\n        li   t1, 96\n        sw   t1, 8(t0)          # length in words\n        li   t1, 1\n        sw   t1, 12(t0)         # go\nwait:   lw   t1, 12(t0)         # status: bit 1 = done\n        andi t1, t1, 2\n        beqz t1, wait\n        li   t1, 1024\n        jr   t1                 # run what was loaded"
            }
          },
          "at": [
            6,
            6
          ],
          "label": "boot ROM"
        },
        {
          "id": "sw",
          "ref": {
            "switches": 8
          },
