              "src": "# computer B: print what arrives; at each new line answer pong\n        li   s0, 0x80000000     # console\n        li   s1, 0x30000000     # UART: data +0, status +4, divisor +8\n        li   t0, 1\n        sw   t0, 8(s1)          # bit rate = clock / (16 · divisor)\nwait:   jal  ra, recv\n        sw   a0, 0(s0)          # print it\n        li   t0, 10\n        bne  a0, t0, wait\n        li   a0, 112            # p\n        jal  ra, send\n        li   a0, 111            # o\n        jal  ra, send\n        li   a0, 110            # n\n        jal  ra, send\n        li   a0, 103            # g\n        jal  ra, send\n        li   a0, 10             # new line ends the message\n        jal  ra, send\n        j    wait\nsend:   lw   t1, 4(s1)          # status\n        andi t1, t1, 2          # transmit FIFO full?\n        bnez t1, send\n        sw   a0, 0(s1)          # queue the byte; the UART frames it\n        ret\nrecv:   lw   t1, 4(s1)\n        andi t1, t1, 1          # receive FIFO empty?\n        beqz t1, recv\n        lw   a0, 0(s1)          # the oldest received byte\n        ret"
