… :xx:xx, then the source's first two bytes\n        sw   a1, 8(t1)          # the source's last four\n        sw   a2, 12(t1)         # type 0800, payload bytes 0 and 1\n        sw   a3, 16(t1)         # payload bytes 2 to 4\n        li   t3, 5\npad:    slli t4, t3, 2\n        add  t4, t4, t1\n        sw   zero, 0(t4)        # zeros up to 60 bytes\n        addi t3, t3, 1\n        li   t5, 15\n        blt  t3, t5, pad\n        li   t2, 0x8000003c     # OWN | 60 bytes\n        sw   t2, 4(t0)\n        li   t2, 1\n        sw   t2, 28(s1)         # KICK: the doorbell\n        addi s4, s4, 1\n        andi s4, s4, 7\n        ret\nrecv:   slli t0, s5, 3\n        add  t0, s2, t0         # receive descriptor\nwait:   lw   t1, 4(t0)\n        bltz t1, wait           # OWN still set: nothing yet\n        lw   t2, 0(t0)          # its buffer\n        lw   t3, 12(t2)         # type, payload 0 and 1\n        srli t4, t3, 16\n        andi t4, t4, 255\n        sw   t4, 0(s0)          # print the payload\n        srli t4, t3, 24\n        sw   t4, 0(s0)\n        lw   t3, 16(t2)\n        andi t4, t3, 255\n        sw   t4, 0(s0)\n        srli t4, t3, 8\n        andi t4, t4, 255\n        sw   t4, 0(s0)\n        srli t4, t3, 16\n        andi t4, t4, 255\n        sw   t4, 0(s0)\n        li   t1, 0x80000000\n        sw   t1, 4(t0)          # give the buffer back\n        addi s5, s5, 1\n        andi s5, s5, 7\n        ret"
